// Extraer datos del webhook de Meta (Instagram Direct o Facebook Messenger)
const body = $input.first().json.body || $input.first().json;

// Detectar si el canal es Instagram o Messenger
let channel = 'instagram';
let senderId = '';
let senderName = 'Clienta';
let messageText = '';
let tenantId = body.tenant_id || 'default-tenant';

if (body.object === 'instagram' || body.entry?.[0]?.messaging?.[0]?.recipient) {
  channel = 'instagram';
  const entry = body.entry?.[0]?.messaging?.[0];
  senderId = entry?.sender?.id || 'ig_user';
  senderName = entry?.sender?.username ? `@${entry.sender.username}` : 'Clienta Instagram';
  messageText = entry?.message?.text || '';
} else if (body.object === 'page') {
  channel = 'messenger';
  const entry = body.entry?.[0]?.messaging?.[0];
  senderId = entry?.sender?.id || 'fb_user';
  senderName = entry?.sender?.name || 'Cliente Facebook';
  messageText = entry?.message?.text || '';
} else {
  senderId = body.from || body.sender?.id || 'user';
  senderName = body.sender?.name || 'Cliente';
  messageText = body.text || body.message?.text || '';
  channel = body.channel || 'instagram';
}

return [{
  json: {
    channel,
    senderId,
    senderName,
    messageText,
    tenantId,
    rawPayload: body
  }
}];

